"""Generate a self-contained, collapsible study guide for the completed train500 experiment."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
chapters=[
('overview','01 项目定位与两分钟讲解','先说明研究问题，再按数据、方法、评估和发现展开。不要从环境安装或GPU数量开始讲。',[
('请用两分钟介绍这个项目。','我基于OpenPI做π0.5在LIBERO Spatial上的任务适配，主要研究固定数据和更新预算下，不同模块更新范围对闭环操作效果的影响。我处理了10个任务的500条示教，依据原始采集时序将观测对齐下一步动作，形成61,750帧监督样本和长度10的动作块。\n我在相同基础权重、global batch32、3,000次更新下，比较动作专家LoRA、双LoRA、视觉等模块联合更新，以及动作专家原权重更新四类策略。评估使用相同的官方10任务×50初态，每次预测10步、执行5步后再观测。双LoRA为28.4%，联合更新方案C为94.8%，扩大动作专家更新范围的D为95.2%。C的可训练参数约为D的53.5%，但成绩只差2个回合。我保留了逐步loss、配对视频和动作记录，用于解释训练拟合与实际闭环表现之间的差异。'),
('这个项目的新意或个人工作在哪里？','模型架构、基础权重和原生Flow Matching来自OpenPI，任务与环境来自LIBERO。项目的工作集中在数据协议、时序对齐、动作块读取、参数更新范围实现、恢复训练、配对评测与结果分析。\n面试时展示get_trainable_filter、get_action_chunk和评估循环等具体代码，说明做了什么、为什么这样做、如何验证。不要把使用现成VLA说成提出了新模型，也不要把工具辅助实现说成未经辅助的独立研究。'),
('现在究竟完成了哪些实验？','本轮500条训练的A–D各完成3,000步；Base与A–D各完成官方500回合评估，共2,500回合。E本轮暂缓。旧450条训练的A–E有另一套完整结果，展示时单独标记。\n当前主结果是Base0%、A3.0%、B28.4%、C94.8%、D95.2%。旧heldout50的74%/92%不再作为本轮成绩。'),
('为什么把C与D的取舍作为核心发现？','C更新466,957,072个参数，D更新872,771,344个参数；C的可训练参数约为D的53.5%。C为474/500，D为476/500。这个结果提出了“扩大更新范围是否值得”的问题。\n不能说C节省46.5%显存，也不能说D稳定更好；推理结构、激活、优化器与冻结参数都影响资源，重复训练稳定性也没有由这两组分数得到证明。')]),
('data','02 数据：从原始轨迹到监督样本','代码入口：scripts/convert_spatial_500.py；src/pi05/dataset.py。先手算一个时间对齐与动作块示例，再看真实函数。',[
('500条、61,750帧、3,000步分别是什么？','500是完整示教轨迹数量，10个任务各50条；61,750是时间对齐后能提供后继动作监督的有效帧数；3,000是优化器更新次数。一次更新使用global batch32个样本，累计96,000次样本访问，约1.55个有效帧总量。\n样本是动作块起点，动作块之间可能重叠；96,000不是96,000条独立轨迹，也不能把3,000步写成3,000个epoch。'),
('为什么obs[t]要对action[t+1]？','原始记录在执行action[t]之后保存observation[t]。部署时模型接收当前观测来预测接下来要执行的动作，因此需要obs[t]对应action[t+1]。直接同下标训练会把已经执行过的动作当成未来动作。\n转换阶段已做这次位移并丢弃末观察；读取Parquet时同行已正确，不再+1。依据来自本数据的采集/记录顺序，不是所有机器人数据都应这样错位。'),
('动作块如何构造，末尾如何处理？','从处理后第i行取actions[i:i+10]，只在同一episode内读取；不够10步时重复最后一个有效动作。原动作是7维增量控制，不再对相邻动作差分，模型变换把动作维度补到32。\n末尾重复会影响监督分布，因此要能说明实现选择。当前不能说用了padding mask忽略尾部，因为这里真实实现是重复末动作。'),
('归一化为什么必须与权重配套？','π0.5这里采用训练集分位数q01/q99进行归一化，并在输出时用同一组统计反变换。动作尺度和状态分布由统计决定；换错统计即使权重相同也会改变控制输出。\n本轮全部500条参与统计；旧450条训练统计独立保留。Base也使用对应本轮统计，所以450/500两轮比较改变了数据和统计，不能隔离出纯数据量效应。'),
('这里有验证集吗？数据与状态进入模型了吗？','本轮没有留出离线验证，validation_mode=none，验证清单为空。旧450/50协议有6,180帧验证，但不能移用到当前结果。\n接口保留8维state，然而本项目π0.5配置discrete_state_input=false且没有连续state token，因此不能仅凭batch字典存在state就说模型使用了数值本体状态条件。双相机与语言是本配置的关键条件输入。')]),
('model','03 模型：Flow Matching 与动作专家','代码入口：src/pi05/model.py 的前向展开、lora_config、get_trainable_filter；训练调用固定版OpenPI原生compute_loss。',[
('Flow Matching在这个项目中学习什么？','学习给定图像、语言、时间t和带噪动作块时的速度场。代码构造x_t=tε+(1−t)a，目标速度u_t=ε−a；模型预测vθ，计算预测与目标的平方误差。\n本代码的t=1对应噪声端，t=0对应动作端。时间来自缩放后的Beta(1.5,1)。应按实际代码说明符号方向，不把其他论文中相反的t定义直接套进来。'),
('训练有真实动作，推理没有，怎么生成动作？','训练用真实动作构造插值状态与目标速度；推理从噪声动作块开始，结合当前视觉语言条件预测速度，多次积分接近动作端，再反归一化为环境控制值。\n本轮denoise_steps=10。它表示生成一个动作块的求解迭代数，不代表只执行10个环境步，也不同于动作块长度或执行长度。'),
('为什么使用动作块，而不是只输出下一步？','动作块同时建模短时序内动作关系，减少每个控制步都完整调用策略的成本。当前预测10步、仅执行前5步，以较新观测进行反馈。\n一次执行更长可能减少调用次数，也可能积累更多开环误差；当前没有执行长度消融，不能声称5步是最优，只能说明这是固定的比较协议。'),
('视觉语言模型和动作专家如何分工？','视觉语言前缀提供任务与场景条件，动作专家处理带噪动作与时间条件并输出动作速度预测。它们通过模型中的注意力结构进行条件交互。\n面试中需沿embed_prefix、embed_suffix、attention mask和action_out_proj实际追踪张量；不要把动作专家误说成训练后接上的独立分类器。若讨论π0与π0.5论文差异，需要区分论文的整体预训练方案与本项目实际启用的输入配置。')]),
('adaptation','04 更新范围：A–E究竟改了什么','代码入口：model.py中的NNX参数过滤器。参数统计来自每组metrics.jsonl的start事件和parameters.json。',[
('请逐个解释A、B、C、D、E。','A：仅动作专家LoRA；B：语言模块与动作专家双LoRA；C：双LoRA加视觉编码器和外部投影等模块更新；D：语言模块LoRA加视觉、外部投影和动作专家原权重更新；E：不添加LoRA，整模型参数更新。\n当前完成的是A–D。E只在旧450训练实验里有结果。Default即C，不是全参数微调。'),
('LoRA参数怎样进入权重更新？','常见写法是W_eff=W+(α/r)BA，原W冻结，训练低秩矩阵A/B。本项目语言模块Attention与FFN的rank/alpha均16，动作专家均32；实际参数名需要覆盖Attention和MLP的LoRA项。\n低秩更新不等于整个模型计算都低秩化，也不自动意味着同等比例推理加速。是否合并、图像前向和激活成本都需要单独说明。'),
('C的“投影层”具体指什么？','过滤器把PaliGemma之外的模型参数划入PROJECTION_FILTER，其中包括动作输入/输出、时间相关外部模块等，不能笼统称为只有视觉投影层。视觉编码器由PaliGemma/img路径单独筛选。\nC可训练参数为双LoRA49,987,584＋视觉414,803,696＋投影等2,165,792，共466,957,072。'),
('这是不是严格的模块因果消融？','固定了训练数据、逐步采样索引、更新预算和闭环协议，适合比较实际配方。但是可训练参数保留FP32、冻结参数转BF16，更新范围变动同时改变部分参数精度；D还改变动作专家的参数化。\n因此可说“在本设置下扩大更新范围对应更好的闭环表现”，不能把66.4个百分点全部解释为视觉编码器单一因素的因果贡献。')]),
('training','05 训练、loss与恢复','代码入口：train.py的TrainState、梯度累积与并行更新；checkpoints.py的保存与恢复。',[
('global batch32如何从4卡得到？','逻辑microbatch为2，共16个microbatch组成一次更新。4卡同时处理4个microbatch，每卡累计4份，最后合并梯度，所以global batch=2×4×4=32。\n配置里的accum_steps=16已经描述总逻辑microbatch数量，不能再乘4变128。学习率调度按优化器更新计数推进。'),
('为什么先跑2步再恢复？恢复了什么？','用于验证完整checkpoint保存和恢复路径，之后追加2,998次更新，总预算仍3,000。需要恢复权重、Adam状态、更新计数、随机状态、采样游标和配置，而不只是载入模型参数。\n如果采样游标或调度计数丢失，会重用不同样本或重新warmup，实验预算表面相同但轨迹不同。'),
('Step3000的loss为什么比最后100步均值小？','Step3000只是该次随机训练批次的loss，最后100步平均包含其他批次。不同样本、噪声和时间t导致波动，因此最后一点不等于收敛后的全数据误差。\n例如C最终点0.022152，但末100步均值0.031552。展示时保留原始曲线、明确EMAα=0.05，并分别标注这两个统计量，不把其中之一冒充验证loss。'),
('训练loss接近，为何B/C闭环差很多？','loss是训练数据上的聚合速度预测误差，闭环要求在模型自己造成的状态下连续执行并满足任务条件。关键动作阶段的偏差、误差累积和诱导状态偏移都可能造成不同结果。\n这是一组可能机制，不能从均值直接确定原因。当前可以用配对录像与动作trace检查具体差异；如果没有逐帧标注，就先报告行为现象而不杜撰原因。'),
('训练耗时图能证明加速吗？','不能直接证明。现有日志提供update_seconds与数据读取时间，图中中位数排除了includes_compile标记的第1、3步。A–D的运行时间和共享资源环境不同，不能作为受控硬件基准。\n可用它描述这轮实际观测与工程规模；若要宣称加速，需要统一硬件、预热、工作负载和测量范围。')]),
('evaluation','06 评估：初态、滚动控制与成功','代码入口：evaluate.py的manifest生成、policy.infer/反归一化/env.step与结果写出。',[
('官方500回合和500条训练示教是什么关系？','训练单位是500条示教轨迹，评估单位是官方Spatial任务的10×50初态，各自有独立的记录格式。评估从环境初态出发由策略自主闭环控制，而不播放示教动作。\n官方初态并不自动意味着未见任务或严格独立隐藏测试集；应准确说“同任务官方初态闭环评估”，不扩大结论。'),
('公平比较具体固定了哪些东西？','相同任务列表、每任务50初态、manifest、seed、逐回合动作噪声规则、渲染与缩放、settle10、最大220控制步、预测10/执行5、denoise10。每组使用与训练配套的全500统计。\n还验证了每组500条唯一(task_id,initial_state_id)、每任务50条、退出码0、errors0，逐回合汇总与summary一致。固定协议减少了比较干扰，但没有消除范围/精度差异。'),
('成功率如何计算？超时算错误吗？','环境任务成功条件满足记为success；到220步还未成功记为timeout，是正常任务失败。运行异常则单独记error，不能与正常失败混为一谈。\n本轮五组errors都为0。D为476次成功除以500，得到95.2%；Base的500次均超时，0%不代表程序崩溃。'),
('为什么只执行预测的前5步？','执行之后环境状态可能偏离预测时的假设，重新观察能提供反馈。剩余未执行动作块丢弃，用新观测重新推理。\ntrace记录完整预测、实际执行、对应预测调用和块内offset，可检查实际执行是否来自预测前缀。该机制是滚动控制，不是执行完10步再询问模型。')]),
('analysis','07 结果分析与追问','不要只记95.2%。练习解释反例、数据版本与配对统计。',[
('D比C高0.4个百分点，是否明显更好？','D比C多2个成功回合；两者共同成功460，C独有成功14，D独有成功16。整体差距小，而且各自有反例。\n当前合理结论是两种方案在该协议下总体接近，D略高；不能宣称稳定显著优势。C使用更少可训练参数，是值得关注的选择。'),
('哪个任务值得优先分析？','任务5：pick up the black bowl on the ramekin and place it on the plate。C为36/50，D为43/50；C总26次失败有14次在该任务，D总24次失败有7次在该任务。\n可以优先查看任务5内的配对成功/失败视频与trace，再形成可验证的失败分类；不能把它误写成抽屉任务，任务号必须按固定LIBERO顺序读取。'),
('增加50条训练示教为什么B反而下降？','旧450条配方B35.8%，新500条配方B28.4%；数据及归一化同时变化，且训练更新预算固定。不能据此断言更多数据伤害性能，也不能声称新方案在所有设置都更好。\n解释时应报告观察到的变化和混杂因素；若未来要隔离机制，需要预先设计对照，而不是这次为了展示再盲目跑实验。'),
('Base为0%，能否说明基础模型没有操作能力？','不能推广。这里是特定任务、图像输入、控制动作空间、归一化和短预算评估下的结果。基础模型对具体环境的适配不足是可能解释，但0%只支持本协议下未成功。\n不能用别的官方适配权重的高分替换Base，也不能把上游预训练覆盖与当前任务关系简单概括成“完全没见过”。')]),
('demo','08 Demo、证据与可复现','将每个可见数字指向真实记录，让观看者能从结果追到配置和源码。',[
('Demo在实时推理吗？','展示页是已有策略闭环执行录像的交互回放；不调用GPU，也不在线生成动作。它支持同初态比较、模型切换、同时播放及图表查看。\n真正的仿真推理仍使用evaluate.py，在准备好项目环境、数据统计和完整checkpoint后执行。仓库没上传大权重，不能声称clone后无需资产即可实时推理。'),
('这些视频是怎样挑的，会不会只挑成功？','四类条件分别为B失败C/D成功、C成功D失败、任务5内D成功C失败、C/D均失败；按(task,init)排序取第一个匹配回合。包含正例与反例，但仍是条件筛选的展示样本。\n整体成功率来自所有500回合，不能根据精选片段估计。media-manifest保留原路径、大小与SHA256，避免误混历史视频。'),
('你的结果能追到哪里？','训练：results/train500/train/<组>/metrics.jsonl、config.json、parameters.json；评估：eval/<组>/summary.json、episodes-*.jsonl、eval_manifest.json；数据：results/dataset；业务源码：src/pi05。\n新仓库是实验后的展示归档，训练原代码提交和导出哈希在provenance.json，不能把新建仓库提交伪称成运行时提交。'),
('下一步最有价值的工作是什么？','先人工标注高价值配对失败，结合实际执行动作检查偏差出现的阶段；若需要继续实验，再围绕一个明确问题设计对照，比如范围与精度分离。\n当前不需要为了补图重跑训练，因为每步loss、学习率、梯度与评估记录已经存在。未经额外授权不追加GPU实验，也不把计划写成已完成。')])]

nav=''.join(f'<a href="#{key}">{escape(title)}</a>' for key,title,_,_ in chapters)
body=[];count=0
md=['# π0.5 train500 学习与面试手册','更新：2026-11-01。准备题，不代表任何公司的真实面经。']
for key,title,intro,qa in chapters:
    part=[f'<section id="{key}"><p class="eyebrow">LEARN / EXPLAIN / VERIFY</p><h2>{escape(title)}</h2><p>{escape(intro)}</p>']
    md += ['\n## '+title,intro]
    for q,a in qa:
        count+=1
        answer=''.join('<p>'+escape(p)+'</p>' for p in a.split('\n'))
        part.append(f'<details><summary>Q{count:02d} · {escape(q)}</summary>{answer}</details>')
        md+=['\n### '+q,a]
    part.append('</section>');body.append(''.join(part))
css=(ROOT/'demo/style.css').read_text()
